def typed_dict_to_dict(typ: type) ->TypeDict:
    d: TypeDict = {
        'module': typ.__module__,
        'qualname': typ.__qualname__,
    }
    fields = {}
    for field_name, field_type in typ.__annotations__.items():
        fields[field_name] = type_to_dict(field_type)
    d['fields'] = fields
    return d
